import pandas as pd


def run(inputs: dict[str, "pd.DataFrame"]) -> dict[str, "pd.DataFrame"]:
    readings = inputs["readings"].copy()

    orig_cols = list(readings.columns)

    def is_bad(v):
        if pd.isna(v):
            return True
        try:
            if v < 0 or v > 1000:
                return True
        except TypeError:
            return True
        return False

    if len(readings) == 0:
        readings["_bad"] = pd.Series(dtype=bool)
    else:
        readings["_bad"] = readings["value"].apply(is_bad)

    clean_parts = []
    reject_parts = []
    quarantine_parts = []

    # preserve first-appearance order of batch_id, and original row order within batch
    for batch_id, g in readings.groupby("batch_id", sort=False):
        total = len(g)
        bad = int(g["_bad"].sum())

        if bad * 100 > total * 20:
            pct = round(bad * 100.0 / total, 2)
            q = g.drop(columns=["_bad"]).copy()
            q["batch_reject_pct"] = pct
            quarantine_parts.append(q)
        else:
            good_g = g[~g["_bad"]].drop(columns=["_bad"])
            bad_g = g[g["_bad"]].drop(columns=["_bad"])
            if len(good_g) > 0:
                clean_parts.append(good_g)
            if len(bad_g) > 0:
                reject_parts.append(bad_g)

    if clean_parts:
        readings_clean = pd.concat(clean_parts, ignore_index=True)
    else:
        readings_clean = pd.DataFrame(columns=orig_cols)

    if reject_parts:
        readings_rejects = pd.concat(reject_parts, ignore_index=True)
    else:
        readings_rejects = pd.DataFrame(columns=orig_cols)

    if quarantine_parts:
        readings_quarantine = pd.concat(quarantine_parts, ignore_index=True)
    else:
        readings_quarantine = pd.DataFrame(columns=orig_cols + ["batch_reject_pct"])

    return {
        "readings_clean": readings_clean,
        "readings_rejects": readings_rejects,
        "readings_quarantine": readings_quarantine,
    }
